import { Column, CreateDateColumn, PrimaryColumn, UpdateDateColumn, VersionColumn } from 'typeorm';

/**
 * Columns every table carries (docs/database-design.md §1). Extend `TenantScopedEntity` or
 * `BranchScopedEntity` for business data; use this directly only for platform tables.
 *
 * Soft delete is opt-in for master data: add
 * `@DeleteDateColumn({ type: 'timestamptz' }) deletedAt: Date | null;` to the entity.
 */
export abstract class AppBaseEntity {
  /**
   * UUIDv7 (time-ordered) generated by PostgreSQL 18 when omitted. Clients may supply their
   * own id (offline POS creates records before they reach the server).
   */
  @PrimaryColumn({ type: 'uuid', default: () => 'uuidv7()' })
  id: string;

  @CreateDateColumn({ type: 'timestamptz' })
  createdAt: Date;

  @UpdateDateColumn({ type: 'timestamptz' })
  updatedAt: Date;

  /** Acting user id; filled from the request context once auth lands. */
  @Column({ type: 'uuid', nullable: true })
  createdBy: string | null;

  @Column({ type: 'uuid', nullable: true })
  updatedBy: string | null;

  /** Optimistic locking: incremented by TypeORM on every save. */
  @VersionColumn({ default: 1 })
  version: number;
}

/**
 * Tenant-owned rows. The table also needs RLS (`enableTenantIsolation` in its migration) and
 * composite indexes/foreign keys that lead with `tenant_id`.
 */
export abstract class TenantScopedEntity extends AppBaseEntity {
  @Column({ type: 'uuid' })
  tenantId: string;
}

/** Rows that belong to one branch (orders, tables, stock, cash drawers…). */
export abstract class BranchScopedEntity extends TenantScopedEntity {
  @Column({ type: 'uuid' })
  branchId: string;
}
